1	package br.com.loja.checkout.aplicacao;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	
6	import org.springframework.stereotype.Service;
7	
8	import br.com.loja.checkout.dominio.Dinheiro;
9	import br.com.loja.checkout.dominio.Item;
10	import br.com.loja.checkout.dominio.PedidoRecusadoException;
11	import br.com.loja.checkout.dominio.Regiao;
12	import br.com.loja.checkout.dominio.Registro;
13	import br.com.loja.checkout.dominio.clube.NivelClube;
14	import br.com.loja.checkout.dominio.cupom.ContextoCupom;
15	import br.com.loja.checkout.dominio.cupom.Cupom;
16	import br.com.loja.checkout.dominio.entrega.ModalidadeEntrega;
17	import br.com.loja.checkout.dominio.pagamento.Cobranca;
18	import br.com.loja.checkout.dominio.pagamento.FormaPagamento;
19	
20	/**
21	 * Calcula o resumo da compra. Este e o unico lugar que conhece a sequencia das
22	 * etapas e a ordem das validacoes; nenhum caso concreto aparece aqui.
23	 */
24	@Service
25	public class ResumoService {
26	
27	    private final Registro<ModalidadeEntrega> modalidadesEntrega;
28	    private final Registro<Cupom> cupons;
29	    private final Registro<NivelClube> niveisClube;
30	    private final Registro<FormaPagamento> formasPagamento;
31	
32	    public ResumoService(Registro<ModalidadeEntrega> modalidadesEntrega,
33	                         Registro<Cupom> cupons,
34	                         Registro<NivelClube> niveisClube,
35	                         Registro<FormaPagamento> formasPagamento) {
36	        this.modalidadesEntrega = modalidadesEntrega;
37	        this.cupons = cupons;
38	        this.niveisClube = niveisClube;
39	        this.formasPagamento = formasPagamento;
40	    }
41	
42	    public Resumo calcular(PedidoSolicitado pedido) {
43	        List<Item> itens = itensDoCarrinho(pedido);
44	        NivelClube nivel = niveisClube.buscar(pedido.nivelClube())
45	                .orElseThrow(() -> recusa("NIVEL_CLUBE_INVALIDO"));
46	        Regiao regiao = Regiao.porCodigo(pedido.regiao())
47	                .orElseThrow(() -> recusa("REGIAO_INVALIDA"));
48	        ModalidadeEntrega entrega = modalidadesEntrega.buscar(pedido.modalidadeEntrega())
49	                .orElseThrow(() -> recusa("MODALIDADE_INVALIDA"));
50	
51	        BigDecimal pesoKg = pesoDoPedido(itens);
52	        if (!entrega.atende(pesoKg)) {
53	            throw recusa("MODALIDADE_INDISPONIVEL");
54	        }
55	
56	        Dinheiro subtotalProdutos = subtotal(itens);
57	        Dinheiro frete = nivel.isentaFrete() ? Dinheiro.ZERO : entrega.frete(pesoKg);
58	        Dinheiro descontoCupom = descontoDoCupom(pedido, new ContextoCupom(itens, subtotalProdutos, frete));
59	
60	        FormaPagamento pagamento = formasPagamento.buscar(pedido.formaPagamento())
61	                .orElseThrow(() -> recusa("FORMA_PAGAMENTO_INVALIDA"));
62	        int parcelas = pedido.parcelasOuUma();
63	        if (!pagamento.parcelasPermitidas(parcelas)) {
64	            throw recusa("PARCELAMENTO_INVALIDO");
65	        }
66	
67	        Dinheiro seguro = regiao.seguro(subtotalProdutos);
68	        Dinheiro totalPedido = subtotalProdutos.menos(descontoCupom).mais(frete).mais(seguro);
69	        if (!pagamento.atende(totalPedido)) {
70	            throw recusa("FORMA_PAGAMENTO_INDISPONIVEL");
71	        }
72	
73	        Cobranca cobranca = pagamento.cobrar(totalPedido, parcelas);
74	        return new Resumo(
75	                subtotalProdutos,
76	                descontoCupom,
77	                frete,
78	                entrega.prazoDias(),
79	                seguro,
80	                cobranca.totalFinal().menos(totalPedido),
81	                cobranca.totalFinal(),
82	                parcelas,
83	                cobranca.valorParcela(),
84	                nivel.credito(subtotalProdutos),
85	                nivel.temBrinde(subtotalProdutos));
86	    }
87	
88	    private List<Item> itensDoCarrinho(PedidoSolicitado pedido) {
89	        List<ItemSolicitado> itens = pedido.itens();
90	        if (itens == null || itens.isEmpty()
91	                || itens.stream().anyMatch(item -> item == null || !item.valido())) {
92	            throw recusa("PEDIDO_INVALIDO");
93	        }
94	        return itens.stream().map(ItemSolicitado::paraItem).toList();
95	    }
96	
97	    private Dinheiro descontoDoCupom(PedidoSolicitado pedido, ContextoCupom contexto) {
98	        if (!pedido.temCupom()) {
99	            return Dinheiro.ZERO;
100	        }
101	        Cupom cupom = cupons.buscar(pedido.cupom()).orElseThrow(() -> recusa("CUPOM_INVALIDO"));
102	        if (!cupom.aplicavel(contexto)) {
103	            throw recusa("CUPOM_NAO_APLICAVEL");
104	        }
105	        return cupom.desconto(contexto);
106	    }
107	
108	    private BigDecimal pesoDoPedido(List<Item> itens) {
109	        return itens.stream().map(Item::pesoTotalKg).reduce(BigDecimal.ZERO, BigDecimal::add);
110	    }
111	
112	    private Dinheiro subtotal(List<Item> itens) {
113	        return itens.stream().map(Item::total).reduce(Dinheiro.ZERO, Dinheiro::mais);
114	    }
115	
116	    private PedidoRecusadoException recusa(String codigo) {
117	        return new PedidoRecusadoException(codigo);
118	    }
119	}
