1	package br.com.loja.checkout.dominio;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	/**
7	 * Valor em dinheiro. Todo valor nasce arredondado para centavos no criterio
8	 * meio-para-o-par, que e o arredondamento usado em todas as etapas do resumo.
9	 */
10	public record Dinheiro(BigDecimal valor) implements Comparable<Dinheiro> {
11	
12	    private static final int CENTAVOS = 2;
13	    private static final RoundingMode CRITERIO = RoundingMode.HALF_EVEN;
14	
15	    public static final Dinheiro ZERO = de("0");
16	
17	    public Dinheiro {
18	        valor = valor.setScale(CENTAVOS, CRITERIO);
19	    }
20	
21	    public static Dinheiro de(String valor) {
22	        return new Dinheiro(new BigDecimal(valor));
23	    }
24	
25	    public static Dinheiro de(BigDecimal valor) {
26	        return new Dinheiro(valor);
27	    }
28	
29	    public Dinheiro mais(Dinheiro outro) {
30	        return new Dinheiro(valor.add(outro.valor));
31	    }
32	
33	    public Dinheiro menos(Dinheiro outro) {
34	        return new Dinheiro(valor.subtract(outro.valor));
35	    }
36	
37	    public Dinheiro vezes(BigDecimal fator) {
38	        return new Dinheiro(valor.multiply(fator));
39	    }
40	
41	    public Dinheiro vezes(int fator) {
42	        return vezes(BigDecimal.valueOf(fator));
43	    }
44	
45	    public Dinheiro divididoPor(int divisor) {
46	        return new Dinheiro(valor.divide(BigDecimal.valueOf(divisor), CENTAVOS, CRITERIO));
47	    }
48	
49	    /** Percentual sobre este valor, ja arredondado para centavos. */
50	    public Dinheiro percentual(BigDecimal taxa) {
51	        return vezes(taxa);
52	    }
53	
54	    public boolean maiorQue(Dinheiro outro) {
55	        return compareTo(outro) > 0;
56	    }
57	
58	    public boolean menorQue(Dinheiro outro) {
59	        return compareTo(outro) < 0;
60	    }
61	
62	    @Override
63	    public int compareTo(Dinheiro outro) {
64	        return valor.compareTo(outro.valor);
65	    }
66	}
