1	package br.com.loja.checkout.dominio.pagamento;
2	
3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	
6	import org.springframework.stereotype.Component;
7	
8	import br.com.loja.checkout.dominio.Dinheiro;
9	
10	/** Ate 3x sem juros; de 4x a 12x com juros de 1,99% ao mes pela tabela Price. */
11	@Component
12	public class Cartao implements FormaPagamento {
13	
14	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
15	    private static final int PARCELAS_SEM_JUROS = 3;
16	    private static final int PARCELAS_MAXIMAS = 12;
17	    private static final MathContext PRECISAO = MathContext.DECIMAL64;
18	
19	    @Override
20	    public String codigo() {
21	        return "CARTAO";
22	    }
23	
24	    @Override
25	    public boolean parcelasPermitidas(int parcelas) {
26	        return parcelas >= 1 && parcelas <= PARCELAS_MAXIMAS;
27	    }
28	
29	    @Override
30	    public boolean atende(Dinheiro totalPedido) {
31	        return true;
32	    }
33	
34	    @Override
35	    public Cobranca cobrar(Dinheiro totalPedido, int parcelas) {
36	        if (parcelas <= PARCELAS_SEM_JUROS) {
37	            return new Cobranca(totalPedido, totalPedido.divididoPor(parcelas));
38	        }
39	        Dinheiro parcela = parcelaPrice(totalPedido, parcelas);
40	        return new Cobranca(parcela.vezes(parcelas), parcela);
41	    }
42	
43	    /** parcela = total x taxa / (1 - (1 + taxa)^-parcelas) */
44	    private Dinheiro parcelaPrice(Dinheiro totalPedido, int parcelas) {
45	        BigDecimal umMaisTaxaElevado = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas);
46	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(umMaisTaxaElevado, PRECISAO));
47	        return Dinheiro.de(totalPedido.valor().multiply(TAXA_MENSAL).divide(divisor, PRECISAO));
48	    }
49	}
