3	import java.util.Collection;
4	import java.util.LinkedHashMap;
5	import java.util.Map;
6	import java.util.Optional;
7	
8	/**
9	 * Registro dos casos de um eixo de variacao, indexados pelo codigo. Escolher um
10	 * caso e buscar aqui; nenhum lugar do sistema decide por cadeia de condicoes.
11	 */
12	public final class Registro<T extends Identificavel> {
13	
14	    private final Map<String, T> porCodigo = new LinkedHashMap<>();
15	
16	    public Registro(Collection<T> casos) {
17	        casos.forEach(caso -> porCodigo.put(caso.codigo(), caso));
18	    }
19	
20	    public Optional<T> buscar(String codigo) {
21	        return Optional.ofNullable(codigo).map(porCodigo::get);
22	    }
23	}
