    \@Test
    void cartao_em_4x_ja_cobra_juros() {
        Resumo resumo = servico.calcular(pedido(List.of(CAMISETA, TENIS),
                "RETIRADA_LOJA", null, "CARTAO", 4, "BRONZE", "SUDESTE"));

