public class C2 { public static void main(String[] a) {
  BigDecimal total = new BigDecimal("413.80"), taxa = new BigDecimal("0.0199");
  int n = 4;
  BigDecimal pow = BigDecimal.ONE.add(taxa).pow(n);
  BigDecimal div = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(pow, MathContext.DECIMAL64));
  BigDecimal p = total.multiply(taxa).divide(div, MathContext.DECIMAL64).setScale(2, RoundingMode.HALF_EVEN);
  System.out.println(p + " " + p.multiply(BigDecimal.valueOf(n)) + " " + p.multiply(BigDecimal.valueOf(n)).subtract(total));
  System.out.println(new BigDecimal("990.00").multiply(new BigDecimal("0.01")).setScale(2, RoundingMode.HALF_EVEN));
}}
EOF
java /tmp/C2.java
